import React from 'react';
import {
  Container,
  Typography,
  Paper,
  Box,
  List,
  ListItem,
  ListItemText,
  Accordion,
  AccordionSummary,
  AccordionDetails
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

export default function FAQ() {
  const preguntasFrecuentes = [
    {
      pregunta: "¿Por qué se desarrolló?",
      respuesta: "El clúster de Raspberry Pi se desarrolló como una iniciativa educativa pensada para que los estudiantes puedan aprender de forma práctica y cercana cómo funciona la tecnología en la nube. Les permite experimentar con conceptos como orquestación, balanceo de carga y redes, utilizando herramientas reales como Kubernetes, pero en un entorno accesible y de bajo costo. Al simular una nube privada, los alumnos pueden desplegar sus propios servicios —como páginas web, bases de datos o foros— y entender cómo se administran en la vida real. Además, al estar basado en Raspberry Pi, el proyecto es económico, eficiente y fomenta el trabajo colaborativo, ya que son los mismos estudiantes quienes gestionan y mantienen estos servicios, acercándose de manera activa al mundo de la infraestructura tecnológica."
    },
    {
      pregunta: "¿Qué se puede alojar en estos servidores?",
      respuesta: "Se pueden alojar páginas web, aplicaciones ligeras, bases de datos, sistemas de foros, microservicios y entornos de desarrollo, siempre considerando las limitaciones de hardware de un Raspberry Pi."
    },
    {
      pregunta: "¿Cómo funciona el balanceo de carga?",
      respuesta: "El balanceo de carga distribuye las solicitudes de los usuarios entre varios nodos del clúster, evitando que un solo servidor se sature y asegurando un mejor rendimiento y disponibilidad."
    },
    {
      pregunta: "¿Cuál es su límite?",
      respuesta: "El límite depende del número de Raspberry Pi y sus especificaciones (RAM, CPU, almacenamiento). Es ideal para pruebas, educación y proyectos pequeños, pero no para entornos de producción a gran escala."
    },
    {
      pregunta: "¿Cuánto cuesta?",
      respuesta: "El costo es relativamente bajo, ya que un Raspberry Pi es económico. El proyecto busca ser accesible y permitir la experimentación sin grandes inversiones."
    },
    {
      pregunta: "¿Qué se puede mejorar?",
      respuesta: "Se pueden mejorar aspectos como la capacidad de procesamiento añadiendo más nodos, implementar almacenamiento distribuido, optimizar la red interna y automatizar más procesos."
    }
  ];

  const integrantes = [
    'Jhair Agila Marquez',
    'Kevin Sarango',
    'Alyce Maldonado',
    'Nayeli Ramírez',
    'Byron Gonzalez'
  ];

  return (
    <Container sx={{ mt: 4 }}>
      {/* Sección de Preguntas Frecuentes */}
      <Box sx={{ backgroundColor: '#0d3b66', borderRadius: 2, p: 3, mb: 4 }}>
        <Typography variant="h5" sx={{ color: 'white', mb: 2 }}>
          Preguntas frecuentes
        </Typography>
        <Paper sx={{ p: 2 }}>
          {preguntasFrecuentes.map((item, idx) => (
            <Accordion key={idx} sx={{ mb: 1 }}>
              <AccordionSummary
                expandIcon={<ExpandMoreIcon />}
                aria-controls={`panel${idx}-content`}
                id={`panel${idx}-header`}
              >
                <Typography sx={{ fontWeight: 'bold', color: '#0d3b66' }}>
                  {item.pregunta}
                </Typography>
              </AccordionSummary>
              <AccordionDetails>
                <Typography sx={{ color: '#333' }}>
                  {item.respuesta}
                </Typography>
              </AccordionDetails>
            </Accordion>
          ))}
        </Paper>
      </Box>

      {/* Sección de Integrantes */}
      <Box sx={{ backgroundColor: '#0d3b66', color: 'white', p: 3, borderRadius: 2 }}>
        <Typography variant="h5" sx={{ mb: 2 }}>
          Integrantes
        </Typography>
        <List>
          {integrantes.map((name, idx) => (
            <ListItem key={idx} sx={{ py: 0 }}>
              <ListItemText primary={name} primaryTypographyProps={{ color: 'white' }} />
            </ListItem>
          ))}
        </List>
      </Box>
    </Container>
  );
}
